<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\AssetLoan; use App\Models\AssetMaintenance; use App\Models\SchoolAsset; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class AssetController extends Controller { public function index(Request $request){$q=SchoolAsset::query()->when($request->filled('q'),fn($q)=>$q->where(fn($q)=>$q->where('name','like','%'.$request->q.'%')->orWhere('code','like','%'.$request->q.'%')))->orderBy('name');return view('admin.assets.index',['assets'=>$q->get(),'users'=>User::where('is_active',true)->orderBy('name')->get(),'loans'=>AssetLoan::with(['asset','borrower'])->latest('borrowed_on')->limit(20)->get(),'maintenances'=>AssetMaintenance::with('asset')->latest('performed_on')->limit(20)->get()]);} public function store(Request $r){SchoolAsset::create($this->data($r));return back()->with('success','Aset ditambahkan.');} public function update(Request $r,SchoolAsset $asset){$asset->update($this->data($r,$asset));return back()->with('success','Aset diperbarui.');} public function destroy(SchoolAsset $asset){$asset->delete();return back()->with('success','Aset dihapus.');} public function storeLoan(Request $r){$d=$r->validate(['school_asset_id'=>['required','exists:school_assets,id'],'borrower_id'=>['nullable','exists:users,id'],'borrower_name'=>['nullable','string','max:150'],'quantity'=>['required','integer','min:1'],'borrowed_on'=>['required','date'],'due_on'=>['nullable','date','after_or_equal:borrowed_on'],'note'=>['nullable','string','max:2000']]);$asset=SchoolAsset::findOrFail($d['school_asset_id']);$used=$asset->loans()->whereNull('returned_on')->sum('quantity');abort_if($used+$d['quantity']>$asset->quantity,422,'Jumlah aset tidak tersedia.');AssetLoan::create($d);$asset->update(['status'=>'dipinjam']);return back()->with('success','Peminjaman aset dicatat.');} public function returnLoan(AssetLoan $loan){$loan->update(['returned_on'=>now()->toDateString()]);if(! $loan->asset->loans()->whereNull('returned_on')->exists())$loan->asset->update(['status'=>'tersedia']);return back()->with('success','Pengembalian aset dicatat.');} public function storeMaintenance(Request $r){$d=$r->validate(['school_asset_id'=>['required','exists:school_assets,id'],'performed_on'=>['required','date'],'type'=>['required','string','max:80'],'cost'=>['nullable','numeric','min:0'],'note'=>['nullable','string','max:2000']]);$asset=SchoolAsset::findOrFail($d['school_asset_id']);AssetMaintenance::create($d);$asset->update(['status'=>'perawatan']);return back()->with('success','Riwayat perawatan dicatat.');} private function data(Request $r,?SchoolAsset $asset=null):array{return $r->validate(['code'=>['required','string','max:50',Rule::unique('school_assets','code')->ignore($asset)],'name'=>['required','string','max:150'],'category'=>['nullable','string','max:100'],'location'=>['nullable','string','max:100'],'quantity'=>['required','integer','min:0'],'condition'=>['required',Rule::in(array_keys(SchoolAsset::CONDITIONS))],'status'=>['required',Rule::in(array_keys(SchoolAsset::STATUSES))],'acquired_on'=>['nullable','date'],'acquisition_value'=>['nullable','numeric','min:0'],'note'=>['nullable','string','max:2000']]);} }
